Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const int MAX_N = 70;
const int MAX_M = 50;
const int LIMIT = 22;

i64 C[MAX_N + 5][MAX_N + 5];

void init() {
    for (int i = 0; i < MAX_N; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i-1][j-1] + C[i-1][j];
        }
    }
}

int n, m, N;
int mid;
int g[MAX_N + 5];

vector<pair<i64, int>> memo_b[MAX_M + 5][MAX_M + 5];
map<i64, i64> memo_a[MAX_M + 5][MAX_M + 5];

i64 best_val = LLONG_MAX;
i64 best_cnt = 0;

void update(i64 val, i64 cnt) {
    if (val < best_val) {
        best_val = val;
        best_cnt = cnt;
    } else if (val == best_val) {
        best_cnt += cnt;
    }
}

void dfs(int pos, int ca, int cb, i64 sum = 0) {
    if (pos == mid) {
        memo_b[ca][cb].emplace_back(sum, 1);
        return;
    }
    for (int c = 0; c < 2; ++c) {
        if (g[pos-1] != -1 && c != g[pos-1]) continue;
        i64 add = 0;
        if (c == 0 && ca > 0) {
            for (int j = 0; j < n; ++j) {
                add += C[ca-1][n-1] * C[cb][j] * C[N-pos][n-j];
            }
            dfs(pos-1, ca-1, cb, sum + add);
        } else if (c == 1 && cb > 0) {
            for (int j = 0; j < n; ++j) {
                add -= C[cb-1][n-1] * C[ca][j] * C[N-pos][n-j];
            }
            dfs(pos-1, ca, cb-1, sum + add);
        }
    }
}

void bfs() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_a[i][j].clear();
        }
    }
    memo_a[0][0][0] = 1;

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            for (auto &[cur, cnt] : memo_a[i][j]) {
                if (i + j == mid) {
                    auto it = lower_bound(memo_b[i][j].begin(), memo_b[i][j].end(), make_pair(-cur, -1));
                    if (it != memo_b[i][j].end()) {
                        update(abs(cur + it->first), cnt * it->second);
                    }
                    if (it != memo_b[i][j].begin()) {
                        --it;
                        update(abs(cur + it->first), cnt * it->second);
                    }
                } else {
                    int idx = i + j;
                    for (int c = 0; c < 2; ++c) {
                        if (g[idx] != -1 && c != g[idx]) continue;
                        int na = i, nb = j;
                        if (c == 0) ++na;
                        else ++nb;
                        if (na <= n+m && nb <= n+m) {
                            i64 delta = 0;
                            if (c == 0) {
                                for (int l = 0; l < n; ++l) {
                                    delta += C[na-1][n-1] * C[nb][l] * C[N-idx-1][n-l];
                                }
                            } else {
                                for (int l = 0; l < n; ++l) {
                                    delta -= C[nb-1][n-1] * C[na][l] * C[N-idx-1][n-l];
                                }
                            }
                            memo_a[na][nb][cur + delta] += cnt;
                        }
                    }
                }
            }
        }
    }
}

void solve() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_b[i][j].clear();
        }
    }
    dfs(N, n+m, n+m);

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            sort(memo_b[i][j].begin(), memo_b[i][j].end());
            vector<pair<i64, int>> tmp;
            int sz = memo_b[i][j].size();
            for (int k = 0; k < sz; ) {
                i64 val = memo_b[i][j][k].first;
                int total = 0;
                while (k < sz && memo_b[i][j][k].first == val) {
                    total += memo_b[i][j][k].second;
                    ++k;
                }
                tmp.emplace_back(val, total);
            }
            memo_b[i][j] = move(tmp);
        }
    }
    bfs();
}

int main() {
#ifdef matthew99
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    init();
    char s[MAX_N + 5];
    scanf("%d %d %s", &n, &m, s);
    N = (n + m) * 2;
    mid = max(0, N - LIMIT);
    memset(g, -1, sizeof(g));

    solve();
    best_cnt = 0;
    for (int i = 0; i < N; ++i) {
        if (s[i] == 'A') g[i] = 0;
        else if (s[i] == 'B') g[i] = 1;
    }
    solve();
    cout << best_cnt << endl;
    return 0;
}
